    "passage": "※다음을 읽고 물음에 답하시오.\n한 음운이 다른 음운의 속성을 닮아 가는 음운 현상을 ‘동화’라고 한다. 이때 동화를 일으키는 음운을 ‘동화음’, 동화음을 닮아 가는 음운을 ‘피동화음’이라고 한다. 동화 현상의 하나인 구개음화는, 경구개가 아닌 위치에서 발음되는 자음이 단모음 ‘ㅣ’나 반모음 ‘’ 앞에서 경구개음으로 바뀌는 음운 현상으로, 피동화음인 자음이 동화음 ‘ㅣ’나 반모음 ‘’가 경구개 부근에서 발음되는 속성을 닮아 가는 것이다.\n구개음화는 피동화음의 종류에 따라 분류할 수 있는데 피동화음이 ‘ㄷ, ㅌ, ㄸ’인 경우는 ‘ㄷ-구개음화’, 피동화음이 ‘ㄱ, ㅋ, ㄲ’인 경우는 ‘ㄱ-구개음화’로 부른다. 현대 국어에서 표준 발음으로 인정되는 구개음화는 ‘ㄷ-구개음화’ 중 다음 두 가지이다. 우선 음절 끝소리가 ‘ㄷ, ㅌ’인 형태소가 단모음 ‘ㅣ’로 시작하는 조사나 접사 같은 형식 형태소와 결합하여 ‘ㅈ, ㅊ’으로 변하는 경우이다. 그리고 음절 끝소리가 ‘ㄷ’이고 뒤에 접사 ‘-히-’가 올 때 ‘ㄷ’과 ‘ㅎ’이 축약되어 ‘ㅌ’이 되고, 이것이 구개음 ‘ㅊ’으로 되는 경우이다.\n과거에는 ‘ㄱ-구개음화’도 일어났다. 방언에서 ‘기름’이 ‘지름’으로 변화된 경우가 이에 해당한다. 이 사례에서 알 수 있듯이 과거에는 구개음화가 형태소 내부에서도 일어날 수 있었으며, 이는 근대 국어 시기에 활발하게 일어났다.\n그런데 현대 국어에는 ‘마디’, ‘견디다’와 같이 과거에 구개음화가 일어났을 법한데 그렇지 않은 단어들이 남아 있다. 이런 단어들은 ‘ㄷ’ 뒤에 오는 모음이 원래 ‘ㅣ’가 아닌 다른 모음이었다는 공통점이 있다. 예를 들어 ‘마디’는 과거에 ‘마듸’였는데, 형태소 내부에서의 구개음화가 사라진 후에 ‘ㅢ’가 ‘ㅣ’로 바뀌었기 때문에 구개음화가 일어나지 않은 채로 남게 된 것이다.\n[A][과거에 일어났던 구개음화와 관련하여 잘못된 교정이 일어나기도 했다. 예를 들어 문헌상으로 ‘김치’의 과거 형태는 ‘딤ᄎᆡ’였는데 구개음화가 일어난 이후 ‘짐ᄎᆡ’로 나타난다. 그런데 언중이 구개음화가 일어난 형태를 원래 형태로 교정하고자 하는 과정에서 원래 형태를 잘못 생각하여 ‘김ᄎᆡ’의 형태로 교정하게 되고 이것이 현재의 ‘김치’가 되었다.]",
    "choices": [
      "O",
      "X"
    ],
    "answer": 1,
    "explanation": "이 선지는 틀린 설명입니다.\n\n원문 해설 — 아래 번호는 원래 문제의 선지 번호입니다. 다른 선지의 설명도 함께 제시합니다.\n현대 국어에서 표준 발음으로 인정되는 구개음화는 음절 끝소리가 ‘ㄷ, ㅌ’인 형태소가 단모음 ‘ㅣ’로 시작하는 조사나 접사 같은 형식 형태소와 결합하여 ‘ㅈ, ㅊ’으로 변하는 경우나, 음절 끝소리가 ‘ㄷ’이고 뒤에 접사 ‘-히-’가 올 때 ‘ㄷ’과 ‘ㅎ’이 축약되어 ‘ㅌ’이 되고 이것이 구개음 ‘ㅊ’으로 되는 경우이다. ‘끝인사’를 [끄친사]로 발음하지 않는 이유는 ‘끝’ 뒤에 붙는 ‘인사’가 형식 형태소가 아니기 때문이다.\n[오답풀이] ① ‘같이’를 [가치]로 발음하는 이유는 표준 발음으로 인정되는 ‘ㄷ-구개음화’가 일어나기 때문이다. ② ‘많지만’을 [만치만]으로 발음하는 이유는 자음 축약이 일어나기 때문이다. 이 경우는 현대 국어에서 표준 발음으로 인정되는 구개음화의 사례가 될 수 없다. ③ ‘맏이’를 [마디]로 발음하지 않는 이유는 ‘ㄷ-구개음화’가 일어난 [마지]가 표준 발음으로 인정되기 때문이다. ④ ‘곁으로’를 [겨츠로]로 발음하지 않는 이유는 연음하여 발음한 [겨트로]가 표준 발음이기 때문이다. 이 경우 현대 국어에서 표준 발음으로 인정되는 구개음화의 사례가 될 수 없다.",
