    "prompt": "ⓐ:‘낮’과 ‘한때’를 이어서 한 마디로 발음한 경우이므로, ㉠에 해당하겠군.",
    "passage": "다음 글을 읽고 물음에 답하시오.\n‘ㅎ’을 포함하고 있는 음운 변동의 양상은 음운 환경에 따라 상이하다. 거센소리되기는 예사소리 ‘ㄱ, ㄷ, ㅂ, ㅈ’과 ‘ㅎ’이 만나서 각각 거센소리 ‘ㅋ, ㅌ, ㅍ, ㅊ’으로 바뀌는 현상으로, 음운 변동의 유형 중 두 개의 음운이 합쳐져 하나의 음운으로 바뀌는 축약에 해당한다. 거센소리되기는 ‘ㅎ’과 예사소리의 배열 순서에 따라 두 가지로 구분할 수 있다.\n첫째, ‘ㅎ’이 예사소리보다 앞에 놓인 거센소리되기이다. 표준 발음법 제12항에서는 ‘ㅎ(ㄶ, ㅀ)’ 뒤에 ‘ㄱ, ㄷ, ㅈ’이 결합되는 경우에는, ‘ㅎ’과 뒤 음절 첫소리가 합쳐져 ‘ㅋ, ㅌ, ㅊ’으로 발음한다고 규정하고 있다. 실제의 예를 보면 ‘놓고[노코]’, ‘않던[안턴]’, ‘닳지[달치]’ 등과 같이 주로 용언 어간 뒤에 어미가 결합할 때 일어난다. 둘째, ‘ㅎ’이 예사소리보다 뒤에 놓인 거센소리되기이다. ‘ㅎ’이 예사소리보다 앞에 놓인 경우에는 항상 거센소리되기가 우선적으로 적용되는 것과 달리, ‘ㅎ’이 예사소리보다 뒤에 놓일 때는 교체나 탈락과 같은 다른 음운 변동보다 거센소리되기가 먼저 적용되기도 하고 나중에 적용되기도 한다. ‘꽂히다[꼬치다]’, ‘밟히다[발피다]’처럼 어근에 ‘ㅎ’으로 시작하는 접미사가 결합하는 경우에는 ㉠예사소리와 ‘ㅎ’이 곧바로 합쳐져 거센소리로 바뀐다. 이에 대하여 표준 발음법 제12항에서는 받침 ‘ㄱ(ㄺ), ㄷ, ㅂ(ㄼ), ㅈ(ㄵ)’이 뒤 음절 첫소리 ‘ㅎ’과 결합되는 경우에는 두 음을 합쳐서 각각 ‘ㅋ, ㅌ, ㅍ, ㅊ’으로 발음한다고 규정하고 있다. 그러나 ‘빚하고[비타고]’처럼 체언에 조사가 결합하거나, ‘닭 한 마리[다칸마리]’처럼 둘 이상의 단어를 이어서 한 마디로 발음하는 경우에는 ㉡다른 음운 변동이 먼저 일어난 후에 거센소리되기가 적용된다. ‘빚하고[비타고]’는 받침 ‘ㅈ’이 ‘ㄷ’으로 교체되고 ‘ㄷ’과 ‘ㅎ’이 합쳐져 거센소리로 바뀐 것이고, ‘닭 한 마리[다칸마리]’는 겹받침 ‘ㄺ’에서 ‘ㄹ’이 탈락하고 ‘ㄱ’과 ‘ㅎ’이 합쳐져 거센소리로 바뀐 것이라고 할 수 있다.\n‘ㅎ’을 포함하고 있는 말이라도 모두 거센소리되기가 적용되는 것은 아니다. ‘낳은[나은]’, ‘않아[아나]’, ‘쌓이다[싸이다]’ 등과 같이 용언 어간 말의 ‘ㅎ’ 뒤에 모음으로 시작하는 어미나 접미사가 결합하는 경우에는 ‘ㅎ’이 탈락한다. 원래 이런 환경에서는 어간 말의 자음이 뒤 음절의 첫소리로 연음되어야 하지만 ‘ㅎ’은 연음되지 않고 탈락하는 것이다. 이러한 ‘ㅎ’ 탈락은 예외 없이 일어난다.\n◦ⓐ낮 한때[나탄때] 내린 비로 이슬이 잔뜩 ⓑ맺힌[매친] 풀밭을 가로질러 ⓒ닭한테[다칸테] 모이를 주고 왔다.\n◦ⓓ곶하고[고타고] 바다로 이어진 산책로를 ⓔ넓히는[널피는] 작업이 진행 중이다.",
    "choices": [
      "O",
      "X"
    ],
    "answer": 1,
    "explanation": "이 선지는 틀린 설명입니다.\n\n원문 해설 — 아래 번호는 원래 문제의 선지 번호입니다. 다른 선지의 설명도 함께 제시합니다.\nⓐ는 받침 ‘ㅈ’이 ‘ㄷ’으로 교체되고 ‘ㄷ’과 ‘ㅎ’이 만나 거센소리 ‘ㅌ’으로 바뀐 것이므로 ㉡에 따른 것이라고 할 수 있다. ② ⓑ는 ‘ㅈ’과 ‘ㅎ’이 곧바로 합쳐져 ‘ㅊ’으로 바뀐 것이므로 ㉠에 따른 것이라고 할 수 있다. ③ ⓒ는 겹받침 ‘ㄺ’에서 ‘ㄹ’이 탈락하고 ‘ㄱ’과 ‘ㅎ’이 만나 거센소리 ‘ㅋ’으로 바뀐 것이므로 ㉡에 따른 것이라고 할 수 있다. ④ ⓓ는 받침 ‘ㅈ’이 ‘ㄷ’으로 교체되고 ‘ㄷ’과 ‘ㅎ’이 만나 ‘ㅌ’으로 바뀐 것이므로 ㉡에 따른 것이라고 할 수 있다. ⑤ ⓔ는 겹받침 ‘ㄼ’의 ‘ㅂ’이 접미사 ‘-히-’의 ‘ㅎ’과 곧바로 합쳐져 ‘ㅍ’으로 바뀐 것이므로 ㉠에 따른 것이라고 할 수 있다.",
