    "answer": 0,
    "explanation": "이 선지는 맞는 설명입니다.\n\n원문 해설 — 아래 번호는 원래 문제의 선지 번호입니다. 다른 선지의 설명도 함께 제시합니다.\nⓐ는 받침 ‘ㅈ’이 ‘ㄷ’으로 교체되고 ‘ㄷ’과 ‘ㅎ’이 만나 거센소리 ‘ㅌ’으로 바뀐 것이므로 ㉡에 따른 것이라고 할 수 있다. ② ⓑ는 ‘ㅈ’과 ‘ㅎ’이 곧바로 합쳐져 ‘ㅊ’으로 바뀐 것이므로 ㉠에 따른 것이라고 할 수 있다. ③ ⓒ는 겹받침 ‘ㄺ’에서 ‘ㄹ’이 탈락하고 ‘ㄱ’과 ‘ㅎ’이 만나 거센소리 ‘ㅋ’으로 바뀐 것이므로 ㉡에 따른 것이라고 할 수 있다. ④ ⓓ는 받침 ‘ㅈ’이 ‘ㄷ’으로 교체되고 ‘ㄷ’과 ‘ㅎ’이 만나 ‘ㅌ’으로 바뀐 것이므로 ㉡에 따른 것이라고 할 수 있다. ⑤ ⓔ는 겹받침 ‘ㄼ’의 ‘ㅂ’이 접미사 ‘-히-’의 ‘ㅎ’과 곧바로 합쳐져 ‘ㅍ’으로 바뀐 것이므로 ㉠에 따른 것이라고 할 수 있다.",
