    "passage": "※다음 글을 읽고 물음에 답하시오.\n합성어는 일반적으로 두 개 이상의 어근이 결합되어 형성된 단어를 말하는데, 분류 기준에 따라 몇 가지로 나눌 수 있다.\n첫째, 합성 명사, 합성 부사, 합성 동사 등과 같이 합성어의 품사를 기준으로 분류할 수 있다. 예를 들어 ‘불꽃’은 명사와 명사가 결합한 합성 명사이고, ‘곧잘’은 부사와 부사가 결합한 합성 부사, ‘힘쓰다’는 명사와 동사가 결합한 합성 동사이다.\n둘째, 대등 합성어, 종속 합성어, 융합 합성어와 같이 결합하는 어근들의 의미 관계를 기준으로 분류할 수 있다. 대등 합성어는 결합하는 어근들의 의미가 대등한 관계를 이루는 것으로,‘앞뒤, 오르내리다’ 등이 여기에 해당한다. 종속 합성어는 선행 어근이 후행 어근을 수식하는 구조로, 선행 어근이 후행 어근에 의미상 종속되어 있는 합성어이다. ‘돌다리, 산길’ 등이 여기에 해당한다. 한편, 융합 합성어는 어근들이 결합하면서 각 어근이 본래 갖고 있던 의미에서 벗어나 새로운 의미를 갖는 합성어를 말한다. 예를 들어 ‘나는 그분께 춘추(春秋)를 여쭈어 보았다.’에서 ‘춘추(春秋)’는 ‘봄’과 ‘가을’이라는 기존의 의미에서 벗어나 ‘어른의 나이를 높여 이르는 말’로 사용된 것이다.\n[A][셋째, 어근의 결합 방식이 국어의 일반적인 통사적 구성과 일치하는지를 기준으로 통사적 합성어와 비통사적 합성어로 분류할 수 있다. 통사적 합성어는 명사와 명사가 결합한 ‘산나물’, 부사와 부사가 결합한 ‘실룩샐룩’, 부사와 용언이 결합한 ‘그만두다’, 연결어미에 의해 용언의 어간과 어간이 결합한 ‘뛰어가다’ 등과 같이 국어의 일반적인 통사적 구성을 따른 합성어를 말한다. 반면 비통사적 합성어는 용언의 어간과 명사가 결합한 ‘접칼’, 연결어미 없이 용언의 어간과 어간이 직접 결합한 ‘굶주리다’, 부사와 명사가 결합한 ‘척척박사’ 등과 같이 국어의 일반적인 통사적 구성과 일치하지 않는 합성어를 말한다.]\n<보기>\n∘ 농부들이 ㉠피땀으로 일군 ㉡논밭에 가을이 왔다.\n∘ 이 ㉢봄비가 그치고 여름이 오면, 포도가 ㉣송이송이 영글어 갈 것이다.",
