    "passage": "<보기>\n접두사는 단어의 앞에 붙어 특정한 뜻을 더하거나 강조하면서 새로운 단어를 만들어 낸다. ㉠접두사가 명사에 결합하여 생성된 단어도 있고, ㉡접두사가 용언에 결합하여 생성된 단어도 있다. ㉢특정한 접두사는 둘 이상의 품사에 결합하여 새로운 단어를 만들어 내기도 한다. 대개의 접두사는 형태가 고정되어 있지만, ‘찰-/차-’가 붙어 만들어진 ‘찰옥수수’, ‘차조’처럼 ㉣주위 환경에 따라 형태가 다른 접두사가 붙어 만들어진 단어도 있다.",
