    "answer": 0,
    "explanation": "이 선지는 맞는 설명입니다.\n\n원문 해설 — 아래 번호는 원래 문제의 선지 번호입니다. 다른 선지의 설명도 함께 제시합니다.\n‘수꿩, 숫양’은 주위 환경에 따라 다른 형태를 가지는 접두사 ‘수-/숫-’이 결합하여 만들어진 단어이지만(㉣), 접두사가 결합하는 단어 ‘꿩’과 ‘양’이 모두 명사이므로 둘 이상의 품사에 결합하여 새로운 단어를 만든다는 설명(㉢)에는 해당하지 않는다.\n[오답풀이] ① ‘군-(접두사)+기침(명사)’, ‘군-(접두사)+살(명사)’이므로 ㉠에 해당한다.\n② ‘빗-(접두사)+나가다(동사)’, ‘빗-(접두사)+맞다(동사)’이며, 동사는 용언이므로 ㉡에 해당한다.\n③ ‘헛-(접두사)+디디다(동사)’, ‘헛-(접두사)+수고(명사)’이므로 ㉢에 해당한다.\n④ ‘새-(접두사)+빨갛다(형용사)’, ‘샛-(접두사)+노랗다(형용사)’이며, 형용사는 용언이므로 ㉡과 ㉣에 모두 해당한다.",
