    "explanation": "이 선지는 맞는 설명입니다.\n\n원문 해설 — 아래 번호는 원래 문제의 선지 번호입니다. 다른 선지의 설명도 함께 제시합니다.\n‘울음보’는 ㉠에서 어근 ‘울음’과 접사 ‘-보’로 분석되고 ㉡에서 어근 ‘울-’과 접사 ‘-(으)ㅁ’으로 분석되므로 적절하다.\n② ‘헛웃음’은 ㉠에서 어근 ‘웃음’과 접사 ‘헛-’으로 분석되고 ㉡에서 어근 ‘웃-’과 접사 ‘-(으)ㅁ’으로 분석된다. 따라서 ㉠에서 어근과 어근으로 분석된다는 진술은 적절하지 않다. ③ ‘손목뼈’는 ㉠에서 어근 ‘손목’과 어근 ‘뼈’로 분석되고 ㉡에서 어근 ‘손’과 어근 ‘목’으로 분석된다. 따라서 ㉠에서 어근과 접사로 분석된다는 진술은 적절하지 않다. ④ ‘얼음길’은 ㉠에서 어근 ‘얼음’과 어근 ‘길’로 분석되고 ㉡에서 어근 ‘얼-’과 접사 ‘-(으)ㅁ’으로 분석된다. 따라서 ㉠에서 어근과 접사로 분석되고, ㉡에서 어근과 어근으로 분석된다는 진술은 적절하지 않다. ⑤ ‘물놀이’는 ㉠에서 어근 ‘물’과 어근 ‘놀이’로 분석되고 ㉡에서 어근 ‘놀-’과 접사 ‘-이’로 분석된다. 따라서 ㉡에서 어근과 어근으로 분석된다는 진술은 적절하지 않다.",
