    "explanation": "이 선지는 맞는 설명입니다.\n\n원문 해설 — 아래 번호는 원래 문제의 선지 번호입니다. 다른 선지의 설명도 함께 제시합니다.\nⒷ의 ‘먹어 치우고 일어났다’는 본용언 ‘먹어’, 보조 용언 ‘치우고’, 본용언 ‘일어났다’의 순서로 연결된 경우이므로 적절하지 않다.\n① Ⓐ의 ‘던져서 베어 버렸다’는 본용언 ‘던져서’, 본용언 ‘베어’, 보조 용언 ‘버렸다’의 순서로 연결된 경우이므로 적절하다. ③ Ⓒ의 ‘깨어 있어 행복했다’는  본용언 ‘깨어’, 보조 용언 ‘있어’, 본용언 ‘행복했다’의 순서로 연결된 경우이므로 적절하다. ④ Ⓓ의 ‘앉아 있게 생겼다’는 본용언 ‘앉아’, 보조 용언 ‘있게’, 보조 용언 ‘생겼다’의 순서로 연결된 경우이므로 적절하다. ⑤ Ⓔ의 ‘먹고 싶게 되었다’는 본용언 ‘먹고’, 보조 용언 ‘싶게’, 보조 용언 ‘되었다’의 순서로 연결된 경우이므로 적절하다.",
