    "prompt": "Ⓓ: ‘앉아’는 어간 ‘앉-’에 보조적 연결어미 ‘-아’가 결합되어 ‘있게’와 연결된 형태이고 ㉢에 해당한다.",
    "passage": "※다음 글을 읽고 물음에 답하시오.\n문장의 주체를 서술하는 기능을 하는 용언은 홀로 쓰이는 본용언과, 홀로 쓰이지 않고 본용언 뒤에서 본용언에 특수한 의미를 더해 주는 보조 용언으로 나눌 수 있다. 예를 들어 ‘불이 꺼져 간다.’라는 문장이 있을 때, ‘꺼져’는 ‘불이 꺼진다.’라는 문장의 서술어로 홀로 쓰일 수 있으므로 본용언이다. 그러나 ‘간다’는 진행의 의미만 더해 주고 있어, ‘불이 간다.’라는 문장의 서술어로 홀로 쓰일 수 없으므로 보조 용언이다.\n보조 용언은 다시 보조 동사와 보조 형용사로 구분될 수 있다. 일반적으로 보조 용언의 품사는 앞에 오는 본용언의 품사에 따른다. 예를 들어 보조 용언 ‘않다’는 앞에 오는 본용언의 품사가 동사이면 보조 동사, 형용사이면 보조 형용사로 쓰인다.　한편 보조 용언의 품사가 보조 용언의 의미에 따라 구분되는 경우도 있다. 예를 들어 보조 용언 ‘하다’가 앞말의 행동이나 상태에 대한 바람이라는 의미를 나타내는 경우에는 보조 동사이다. 또한 보조 용언 ‘보다’가 어떤 일을 경험한다는 의미를 나타내는 경우에는 보조 동사이고, 앞말이 뜻하는 행동이나 상태에 대한 걱정이라는 의미를 나타내는 경우에는 보조 형용사이다.\n본용언은 주로 본용언의 어간에 보조적 연결어미가 결합되어 보조 용언과 연결된다. 예를 들어 ‘나는 일을 하고 나서 집에 갔다.’라는 문장은 본용언의 어간 ‘하-’에 보조적 연결어미 ‘-고’가 결합된 ‘하고’가 보조 용언 ‘나서’와 연결된 문장이다. 그리고 본용언과 보조 용언이 연결되는 경우들을 살펴보면, 보통 두 용언이 연결되는 경우가 많지만 의미의 추가를 위해 세 용언이 연결되는 경우도 있다. 여기에는 용언들이 ㉠본용언, 본용언, 보조 용언의 순서로 연결된 경우, ㉡본용언, 보조 용언, 본용언의 순서로 연결된 경우, ㉢본용언, 보조 용언, 보조 용언의 순서로 연결된 경우가 있다.\n\n<보기>\nⒶ 그는 순식간에 사과를 던져서 베어 버렸다.\nⒷ 그는 식당에서 고기를 먹어 치우고 일어났다.\nⒸ 그에게 전화를 했을 때 그가 깨어 있어 행복했다.\nⒹ 나는 경기에 출전하지 못하고 의자에 앉아 있게 생겼다.\nⒺ 나는 평소 밥을 좋아하는데 오늘은 갑자기 빵을 먹고 싶게 되었다.",
