    "answer": 0,
    "explanation": "이 선지는 맞는 설명입니다.\n\n원문 해설 — 아래 번호는 원래 문제의 선지 번호입니다. 다른 선지의 설명도 함께 제시합니다.\n‘-음1’의 용례 ‘믿었음’ 뒤에 결합한 ‘이’는 주격 조사이며, ‘옳음’ 뒤에 결합한 ‘을’은 목적격 조사이다. ‘-음2’의 용례 ‘믿음’, ‘묶음’ 뒤에 결합한 ‘을’은 목적격 조사로 ‘-음2’의 뒤에도 ‘-음1’과 마찬가지로 격조사가 결합할 수 있음을 확인할 수 있다.\n[오답풀이] ① ‘-음1’의 뜻풀이 중 ‘어미 ‘-었-’, ‘-겠-’ 뒤에 붙어’와 제시된 용례인 ‘믿었음’을 통해 확인할 수 있다. ② ‘-음1’은 용언의 어간 뒤에 붙는 어미로, ‘-음1’이 결합한 말은 용언의 활용형이므로 본래의 품사는 그대로 유지된다. ③ ‘-음2’의 용례 ‘그는 서랍에서 종이 한 묶음을 꺼냈다.’에서 ‘묶음’을 수식하는 관형어 ‘한’을 통해 확인할 수 있다. ⑤ ‘-음1’의 뜻풀이를 보면 ‘-음1’은 용언이 명사 구실을 하게 하는 명사형 어미로서, 제시된 용례인 ‘믿었음’과 ‘옳음’은 각각 주어인 ‘그는’과 ‘그의 판단이’와 어울려 명사절을 형성함을 알 수 있다. 반면, ‘-음2’의 뜻풀이를 보면 ‘-음2’는 명사를 만드는 접미사로 명사절을 만들 수는 없다.",
