    "concept": "품사·용언의 문법 환경",
    "prompt": "ㄷ의 ‘무렵’은 서술격 조사 ‘이다’와만 결합할 수 있으므로 후행어 제약이 있군.",
    "passage": "※다음 글을 읽고 물음에 답하시오.\n명사는 자립성의 유무에 따라 자립 명사와 의존 명사로 나눌 수 있다. 가령 ‘새 물건이 있다.’에서 ‘물건’은 관형어인 ‘새’가 없이 단독으로 쓰일 수 있기 때문에 자립 명사이다. 이와 달리 ‘헌 것이 있다.’에서 ‘것’은 관형어인 ‘헌’이 생략되면 ‘것이 있다.’와 같이 문법에 맞지 않는 문장이 되므로 의존 명사이다. 이처럼 의존 명사는 관형어의 수식 없이 단독으로 쓰일 수 없으며 조사와 결합한다는 특징이 있다.\n의존 명사는 특정한 형태의 관형어를 요구하는 선행어 제약과, 특정 서술어나 격 조사와만 결합하는 후행어 제약이 있다. 다음 예문에서 (ㄱ)은 선행어 제약을, (ㄴ)은 후행어 제약을 보여 준다.\n(ㄱ) 여기 (온 / *오는 / *올 / *오던) 지가 오래되었다.\n(ㄴ) 나는 공부를 할 수가 있다.\n그는 좋아서 어쩔 줄을 몰랐다.\n일어난 김에 일을 마무리하자.\n우리는 네게 그저 고마울 따름이다.\n(ㄱ)에서 ‘지’를 수식하는 관형어는 관형사형 어미 ‘-(으)ㄴ’과만 결합하므로 선행어가 제약된다. (ㄴ)에서 ‘수’는 주격 조사 ‘가’와, ‘줄’은 목적격 조사 ‘을’과, ‘김’은 부사격 조사 ‘에’와, ‘따름’은 서술격 조사 ‘이다’와만 결합하므로 후행어가 제약된다. 이와 달리 ‘것’은 결합할 수 있는 격 조사의 제약이 없이 두루 사용된다. 의존 명사가 선행어 제약이나 후행어 제약이 있는지를 판단할 때는 의존 명사가 쓰일 수 있는 다양한 예를 고려해야 한다.\n[A][한편 의존 명사 중에는 ‘만큼’과 같이 동일한 형태가 조사로도 쓰이는 경우가 있는데, 이처럼 하나의 형태가 여러 개의 품사로 쓰이는 것을 품사 통용이라 한다. 예를 들어 ‘먹을 만큼 먹었다.’의 ‘만큼’은 관형어 ‘먹을’의 수식을 받는 의존 명사이지만, ‘너만큼 나도 할 수 있다.’의 ‘만큼’은 체언 ‘너’ 뒤에 붙는 조사이다. 이때 의존 명사는 앞말과 띄어 쓰고, 조사는 앞말과 붙여 써야 한다.]\n<보기>\nㄱ. 우리는 어찌할 바를 모르겠다.\nㄴ. 그들은 칭찬을 받을 만도 하다.\nㄷ. 그를 만난 것은 해 질 무렵이다.\nㄹ. 동생이 그런 일을 할 리가 없다.\nㅁ. 포수는 호랑이를 산 채로 잡았다.",
    "choices": [
      "O",
      "X"
    ],
    "answer": 1,
    "explanation": "이 선지는 틀린 설명입니다.\n\n원문 해설 — 아래 번호는 원래 문제의 선지 번호입니다. 다른 선지의 설명도 함께 제시합니다.\n의존 명사 ‘만’을 수식하는 관형어는 관형사형 어미 ‘-(으)ㄹ’과만 결합할 수 있으므로 선행어 제약이 있다.\n[오답풀이] ① 의존 명사 ‘바’는 ‘바가’와 같이 목적격 조사 이외에 다른 조사와도 결합할 수 있으므로 후행어 제약이 없다. ③ 의존 명사 ‘무렵’은 ‘무렵에’와 같이 서술격 조사 이외에 다른 조사와도 결합할 수 있으므로 후행어 제약이 없다. ④ 의존 명사 ‘리’는 주격 조사와만 결합할 수 있으므로 후행어 제약이 있다. ⑤ 의존 명사 ‘채’를 수식하는 관형어는 관형사형 어미 ‘-(으)ㄴ’과만 결합할 수 있으므로 선행어 제약이 있다.",
