    "answer": 1,
    "explanation": "이 선지는 틀린 설명입니다.\n\n원문 해설 — 아래 번호는 원래 문제의 선지 번호입니다. 다른 선지의 설명도 함께 제시합니다.\n의존 명사 ‘만’을 수식하는 관형어는 관형사형 어미 ‘-(으)ㄹ’과만 결합할 수 있으므로 선행어 제약이 있다.\n[오답풀이] ① 의존 명사 ‘바’는 ‘바가’와 같이 목적격 조사 이외에 다른 조사와도 결합할 수 있으므로 후행어 제약이 없다. ③ 의존 명사 ‘무렵’은 ‘무렵에’와 같이 서술격 조사 이외에 다른 조사와도 결합할 수 있으므로 후행어 제약이 없다. ④ 의존 명사 ‘리’는 주격 조사와만 결합할 수 있으므로 후행어 제약이 있다. ⑤ 의존 명사 ‘채’를 수식하는 관형어는 관형사형 어미 ‘-(으)ㄴ’과만 결합할 수 있으므로 선행어 제약이 있다.",
