    "explanation": "이 선지는 맞는 설명입니다.\n\n원문 해설 — 아래 번호는 원래 문제의 선지 번호입니다. 다른 선지의 설명도 함께 제시합니다.\n‘차가 경적을 울리며 멈추다.’에서 ‘멈추다’는 ‘사물의 움직임이나 동작이 그치다.’라는 의미를 지니므로 ‘멈추다[1]｢1｣’의 용례에 해당한다.\n[오답풀이] ① ‘그치다｢1｣’의 문형 정보 ‘【(…을)】’에서 ‘그치다｢1｣’은 주어만을 필요로 하는 자동사로도 쓰이고, 대상이 되는 목적어를 필요로 하는 타동사로도 쓰임을 알 수 있으며, 이는 ‘그치다｢1｣’이 자동사로 쓰일 때의 용례 ‘비가 그치다.’와 타동사로 쓰일 때의 용례 ‘아이가 울음을 그치다.’에서 재확인할 수 있다. ② ‘그치다｢2｣’의 문형 정보 ‘【…에】【…으로】’에서 ‘그치다｢2｣’가 부사어를 반드시 필요로 함을 알 수 있으며, 이는 용례의 부사어 ‘절반 정도에’, ‘예감으로’를 통해 재확인할 수 있다. ④ 다의어란 두 가지 이상의 뜻을 가진 단어로, ‘그치다’와 ‘멈추다’는 하나의 표제어 아래에 두 가지 이상의 의미가 제시되어 있으므로 다의어이다. ⑤ ‘그치다｢1｣’과 ‘멈추다’의 뜻풀이와 용례를 보면 ‘그치다｢1｣’은 ‘일이나 움직임이 멈추거나 끝나다. 또는 그렇게 하다.’라는 뜻을, ‘멈추다’는 ‘사물의 움직임이나 동작이 그치다. 또는 그치게 하다.’라는 유사한 의미를 지니고 있음을 확인할 수 있으므로 두 단어는 유의 관계에 있다.",
