    "passage": "<보기>\n그치다｢동사｣\n｢1｣【(…을)】계속되던 일이나 움직임이 멈추거나 끝나다. 또는 그렇게 하다.¶비가 그치다./울음을 그치다.\n｢2｣【…에】【…으로】더 이상의 진전이 없이 어떤 상태에 머무르다.¶출석률이 절반 정도에 그쳤다./예감이 예감으로 그치지 않고 현실이 되는 경우가 있다.\n멈추다｢동사｣\n[1]｢1｣사물의 움직임이나 동작이 그치다.¶시계가 멈추다./울음소리가 멈추다.｢2｣비나 눈 따위가 그치다.¶멈추었던 비가 다시 내리기 시작했다.\n[2]【…을】사물의 움직임이나 동작을 그치게 하다.¶기계를 멈추다./발걸음을 멈추다.",
