    "prompt": "보조 동사와 보조 형용사를 다음과 같이 분류한 것은 적절하다.\n보조 동사: ⓐ, ⓒ\n보조 형용사: ⓑ, ⓓ, ⓔ",
    "passage": "보조 용언의 분류 기준: ‘않다’는 앞에 오는 본용언의 품사에 따라 보조 동사 또는 보조 형용사로 분류한다. ‘보다’는 걱정을 나타내면 보조 형용사, 경험을 나타내면 보조 동사이다. ‘하다’는 바람을 나타내면 보조 동사이다.\n\n<보기>\n∘ 내일 해야 할 업무가 생각만큼 쉽지는 ⓐ않겠다.\n∘ 나는 부모님께 야단맞을까 ⓑ봐 얘기도 못 꺼냈다.\n∘ 일을 마무리했음에도 사람들은 집에 가지 ⓒ않았다.\n∘ 새로 일할 사람이 업무 처리에 항상 성실했으면 ⓓ한다.\n∘ 이런 일을 당해 ⓔ보지 않은 사람은 내 심정을 모를 것이다.\n보조 동사\n보조 형용사",
