    "concept": "절 구조·문장 성분 탐구",
    "prompt": "(가)에서 ㉠과 ㉡의 위치를 바꾸면 의미가 달라진다.",
    "passage": "<보기>\n겹문장 속에서 하나의 ‘주어+서술어’ 관계가 이루어진 부분을 ‘절’이라고 한다. ‘절’은 전체 문장의 한 성분으로 안기거나 서로 이어지거나 한다.\n[밑줄 친 절 표시]\n(가) ㉠봄이 오면 ㉡꽃이 핀다.\n(나) ㉢눈이 내린 ㉣마을은 고요했다.\n(다) 나는 ㉤그가 왔음을 몰랐다.",
    "choices": [
      "O",
      "X"
    ],
    "answer": 0,
    "explanation": "이 선지는 맞는 설명입니다.\n\n원문 해설 — 아래 번호는 원래 문제의 선지 번호입니다. 다른 선지의 설명도 함께 제시합니다.\n겹문장은 절과 절이 이어지거나 절이 전체 문장의 한 성분으로 안기면서 이루어진다. (나)와 (다)에서 ㉢과 ㉤은 전체 문장의 관형어와 목적어 기능을 하며 안기어 있다. (가)는 ㉠과 ㉡의 절이 이어져 이루어진 겹문장이다.\n[오답풀이] ① ㉠은 ㉡에 대하여 ‘조건’의 의미를 갖는다. 따라서 두 절의 위치를 바꾸면 의미가 달라진다.\n② ㉢은 관형절로 ‘마을’을 꾸며 주는 역할을 한다.\n③ ㉤은 명사절로 전체 문장의 목적어 역할을 한다. 따라서 목적어가 생략될 경우 전체 문장의 의미는 불완전해진다.\n⑤ (가)~(다)는 모두 ‘주어+서술어’의 관계가 문장 속에 두 번씩 나타나고 있는 겹문장이다.",
