    "passage": "<학습 활동>\n다른 문장에 들어가 하나의 성분처럼 쓰이는 문장을 안긴문장이라고 하고, 이 문장을 포함한 문장을 안은문장이라고 한다. 안긴문장을 절이라고 하는데 그 종류로는 명사절, 관형절, 부사절, 서술절, 인용절이 있다. 예를 들어 관형절은 안은문장 안에서 절 전체가 관형어의 기능을 한다.\n다음 자료에서 안긴문장의 종류와 기능을 파악해 보자.\n[자료]\n㉠누나가 주인임이 밝혀졌다.\n㉡삼촌은 농담을 던짐으로써 분위기를 풀었다.\n㉢형은 동생이 고향으로 돌아오기만 기다렸다.",
