    "concept": "절 구조·문장 성분 탐구",
    "prompt": "ㄴ은 안긴문장과 안은문장의 공통된 체언이 생략되지 않고 관형절이 만들어졌다는 점에서 Ⓑ와 같은 유형이다.",
    "passage": "<보기>\n선생님 : 문장에서 체언을 수식하는 관형어로 쓰이는 절을 관형절이라고 합니다. 오늘은 관형절을 안은 문장의 두 유형에 대해 배워 봅시다.\n안긴문장\n+\n안은문장\n내가 책을 읽는다.\n형이 책을 가져갔다.\n⇓\nⒶ\n관형절을 안은 문장\n형이 [내가 읽는] 책을 가져갔다.\n안긴문장\n+\n안은문장\n지구가 둥글다.\n나는 사실을 안다.\n⇓\nⒷ\n관형절을 안은 문장\n나는 [지구가 둥글다는] 사실을 안다.\n위에서 보듯이, Ⓐ의 유형처럼 안은문장과 공통된 체언이 생략된 관형절을 안은 문장이 있고, Ⓑ의 유형처럼 생략된 성분 없이 문장의 필수 성분을 완전하게 갖춘 관형절을 안은 문장이 있습니다.\n[탐구 과제]\n◦ 다음의 관형절을 안은 문장들을 탐구해 보자.\nㄱ. 그가 지은 시는 감동적이었다.\nㄴ. 나는 벽에 걸려 있던 사진을 떠올렸다.\nㄷ. 나는 그가 한국에 돌아왔다는 소문을 들었다.\nㄹ. 그 사람이 나를 속일 가능성은 매우 낮다.\nㅁ. 나는 수건으로 이마에 흐르는 땀을 닦았다.",
    "choices": [
      "O",
      "X"
    ],
    "answer": 1,
    "explanation": "이 선지는 틀린 설명입니다.\n\n원문 해설 — 아래 번호는 원래 문제의 선지 번호입니다. 다른 선지의 설명도 함께 제시합니다.\nㄴ은 안긴문장 ‘사진이 벽에 걸려 있다.’와 안은문장 ‘나는 사진을 떠올렸다.’에서 공통된 체언인 ‘사진’이 생략된 관형절을 안은 문장이라는 점에서 Ⓐ와 같은 유형이므로 적절하지 않다.\n① ㄱ은 안긴문장 ‘그가 시를 지었다.’에서 안은문장‘시는 감동적이었다.’와의 공통된 체언인 ‘시’를 생략하여 관형절 ‘그가 지은’을 만들었다는 점에서 적절하다. ③ ㄷ은 ‘그가 한국에 돌아왔다.’라는 안긴문장이 생략된 성분 없이 체언 ‘소문’을 수식하는 관형어로 쓰이고 있다는 점에서 적절하다. ④ ㄹ은 관형절인 ‘그 사람이 나를 속일’이 문장의 필수 성분을 모두 갖추고 있다는 점에서 적절하다. ⑤ ㅁ은 안긴문장 ‘땀이 이마에 흘렀다.’와 안은문장 ‘나는 수건으로 땀을 닦았다.’의 공통된 체언인 ‘땀’이 관형절 ‘이마에 흐르는’에서 생략되어 있다는 점에서 적절하다.",
    "choiceExplanations": [
      "O 판단은 맞지 않습니다. 이 선지는 틀린 설명입니다.\n\n원문 해설 — 아래 번호는 원래 문제의 선지 번호입니다. 다른 선지의 설명도 함께 제시합니다.\nㄴ은 안긴문장 ‘사진이 벽에 걸려 있다.’와 안은문장 ‘나는 사진을 떠올렸다.’에서 공통된 체언인 ‘사진’이 생략된 관형절을 안은 문장이라는 점에서 Ⓐ와 같은 유형이므로 적절하지 않다.\n① ㄱ은 안긴문장 ‘그가 시를 지었다.’에서 안은문장‘시는 감동적이었다.’와의 공통된 체언인 ‘시’를 생략하여 관형절 ‘그가 지은’을 만들었다는 점에서 적절하다. ③ ㄷ은 ‘그가 한국에 돌아왔다.’라는 안긴문장이 생략된 성분 없이 체언 ‘소문’을 수식하는 관형어로 쓰이고 있다는 점에서 적절하다. ④ ㄹ은 관형절인 ‘그 사람이 나를 속일’이 문장의 필수 성분을 모두 갖추고 있다는 점에서 적절하다. ⑤ ㅁ은 안긴문장 ‘땀이 이마에 흘렀다.’와 안은문장 ‘나는 수건으로 땀을 닦았다.’의 공통된 체언인 ‘땀’이 관형절 ‘이마에 흐르는’에서 생략되어 있다는 점에서 적절하다.",
      "X 판단이 맞습니다. 이 선지는 틀린 설명입니다.\n\n원문 해설 — 아래 번호는 원래 문제의 선지 번호입니다. 다른 선지의 설명도 함께 제시합니다.\nㄴ은 안긴문장 ‘사진이 벽에 걸려 있다.’와 안은문장 ‘나는 사진을 떠올렸다.’에서 공통된 체언인 ‘사진’이 생략된 관형절을 안은 문장이라는 점에서 Ⓐ와 같은 유형이므로 적절하지 않다.\n① ㄱ은 안긴문장 ‘그가 시를 지었다.’에서 안은문장‘시는 감동적이었다.’와의 공통된 체언인 ‘시’를 생략하여 관형절 ‘그가 지은’을 만들었다는 점에서 적절하다. ③ ㄷ은 ‘그가 한국에 돌아왔다.’라는 안긴문장이 생략된 성분 없이 체언 ‘소문’을 수식하는 관형어로 쓰이고 있다는 점에서 적절하다. ④ ㄹ은 관형절인 ‘그 사람이 나를 속일’이 문장의 필수 성분을 모두 갖추고 있다는 점에서 적절하다. ⑤ ㅁ은 안긴문장 ‘땀이 이마에 흘렀다.’와 안은문장 ‘나는 수건으로 땀을 닦았다.’의 공통된 체언인 ‘땀’이 관형절 ‘이마에 흐르는’에서 생략되어 있다는 점에서 적절하다."
    ],
