    "passage": "<보기>\n선생님 : 문장에서 체언을 수식하는 관형어로 쓰이는 절을 관형절이라고 합니다. 오늘은 관형절을 안은 문장의 두 유형에 대해 배워 봅시다.\n안긴문장\n+\n안은문장\n내가 책을 읽는다.\n형이 책을 가져갔다.\n⇓\nⒶ\n관형절을 안은 문장\n형이 [내가 읽는] 책을 가져갔다.\n안긴문장\n+\n안은문장\n지구가 둥글다.\n나는 사실을 안다.\n⇓\nⒷ\n관형절을 안은 문장\n나는 [지구가 둥글다는] 사실을 안다.\n위에서 보듯이, Ⓐ의 유형처럼 안은문장과 공통된 체언이 생략된 관형절을 안은 문장이 있고, Ⓑ의 유형처럼 생략된 성분 없이 문장의 필수 성분을 완전하게 갖춘 관형절을 안은 문장이 있습니다.\n[탐구 과제]\n◦ 다음의 관형절을 안은 문장들을 탐구해 보자.\nㄱ. 그가 지은 시는 감동적이었다.\nㄴ. 나는 벽에 걸려 있던 사진을 떠올렸다.\nㄷ. 나는 그가 한국에 돌아왔다는 소문을 들었다.\nㄹ. 그 사람이 나를 속일 가능성은 매우 낮다.\nㅁ. 나는 수건으로 이마에 흐르는 땀을 닦았다.",
