    "answer": 0,
    "explanation": "이 선지는 맞는 설명입니다.\n\n원문 해설 — 아래 번호는 원래 문제의 선지 번호입니다. 다른 선지의 설명도 함께 제시합니다.\n㉠의 주동문의 주어 ‘철수가’는 사동문에서 ‘철수를’이라는 목적어로 바뀌었지만, ㉡의 주동문의 주어 ‘동생이’는 사동문에서 ‘동생에게’라는 부사어로 바뀌었으므로 적절하지 않다.\n①　㉡의 사동문은 ‘-이-’라는 사동 접미사를 활용한 형태를 보이고 있다. 하지만 ㉠은 사동 접미사를 활용한 사동문을 만들 수 없으므로 적절하다. ② ㉢의 사동문에서 사동 접미사 ‘-기-’ 대신 ‘-게 하다’를 활용해 사동문을 만들면 ‘인부들이 이삿짐을 방으로 옮게 하다.’와 같이 어색한 문장이 되므로 적절하다. ④ ㉠과 ㉡은 모두 주동문이 사동문으로 되면서 ‘내가’와 ‘누나가’라는 새로운 주어가 생겼으므로 적절하다. ⑤ ㉠, ㉡과 달리 ㉢은 사동문에 대응하는 주동문이 비문이므로 적절하다.",
