    "prompt": "㉠을 보니, 피동 표현을 통해 행위의 대상인 ‘그’를 부각할 수 있겠군요.",
    "passage": "<보기>\n학생: 선생님, 피동 표현은 어떤 경우에 사용하나요?\n선생님: 피동 표현은 행위의 주체보다 대상을 부각하고 싶을 때, 행위의 주체를 분명하게 밝히지 않고자 할 때, 행위의 주체가 중요하지 않거나 누구나 아는 사람이어서 말할 필요가 없을 때 사용해요. 또한 행위의 주체를 분명히 설정하기 어려운 경우에 사용하기도 해요. 이제 아래 자료를 보고 피동 표현에 대해 탐구해 봅시다.\n㉠\n벌이 그를 쏘았다.\n그가 벌에 쏘였다.\n㉡\n내가 편지를 찢었다.\n편지가 찢어졌다.\n㉢\n기자가 내 이야기를 신문에 실었다.\n내 이야기가 신문에 실렸다.\n㉣\n국민들이 대통령을 뽑았다.\n대통령이 뽑혔다.\n㉤\n*A가 추웠던 날씨를 풀었다.\n추웠던 날씨가 풀렸다.\n※ ‘*’는 문법에 맞지 않음을 나타냄.\n학생:\n[A]\n선생님: 네, 맞아요.",
    "choices": [
      "O",
      "X"
    ],
    "answer": 0,
    "explanation": "이 선지는 맞는 설명입니다.\n\n원문 해설 — 아래 번호는 원래 문제의 선지 번호입니다. 다른 선지의 설명도 함께 제시합니다.\n㉣에서 ‘대통령’을 뽑은 행위의 주체는 ‘국민들’이다. ㉣은 행위의 주체가 누구나 아는 사람이어서 말할 필요가 없을 때 피동 표현을 사용할 수 있는 경우이다.\n① ㉠에서 쏘는 행위의 주체는 ‘벌’이고 행위의 대상은 ‘그’이다. ㉠은 ‘그’를 부각하기 위해 피동 표현을 사용한 경우이다. ② ㉡은 피동 표현을 통해 ‘편지’를 찢은 주체인 ‘나’를 밝히지 않고 있다. ③ ㉢은 행위의 주체인 ‘기자’가 중요하지 않을 때 피동 표현을 사용할 수 있는 경우이다. ⑤ ㉤은 ‘날씨’를 푼 행위의 주체를 분명히 설정하기 어려워 피동 표현을 사용한 경우이다.",
