    "passage": "※다음 글을 읽고 물음에 답하시오.\n높임 표현은 높임의 대상에 따라 주체 높임, 객체 높임, 상대 높임으로 나뉜다. 주체 높임은 서술의 주체, 곧 문장의 주어가 지시하는 대상을 높이는 것이다. 현대 국어의 주체 높임은 선어말 어미 ‘-(으)시-’나 주격 조사 ‘께서’, 특수 어휘 ‘잡수다’, ‘계시다’ 등을 통해 실현된다. 중세 국어의 주체 높임도 선어말 어미 ‘-(ᄋᆞ/으)시-’로 실현되었으며, 이는 ‘-(ᄋᆞ/으)샤-’로도 나타났다. 또한 ‘좌시다’, ‘겨시다’ 등의 높임을 나타내는 특수 어휘도 존재하였다.\n[A][주체 높임은 일반적으로 주체의 나이가 화자보다 많거나 사회적 지위 등이 화자보다 높을 때 실현된다. 하지만 주체와 청자의 관계, 담화 상황 등을 고려하여 주체가 높임의 대상이라도 높이지 않거나, 주체가 높임의 대상이 아니라도 높이기도 한다. 가령 방송과 같은 공적 담화에서는 객관성을 고려하여 주체를 높이지 않는 경우가 있다. 또한 주체의 신체 일부, 소유물 등 주체와 밀접한 관련이 있는 대상을 높임으로써 주체를 간접적으로 높일 수도 있는데, 이를 간접 높임이라고 한다.]\n객체 높임은 서술의 객체인, 문장의 목적어나 부사어가 지시하는 대상을 높이는 것이다. 현대 국어의 객체 높임은 부사격 조사 ‘께’나 ‘모시다’, ‘여쭙다’ 등의 특수 어휘를 통해서만 실현된다. 중세 국어의 객체 높임은 부사격 조사 ‘ᄭᅴ’나 ‘뫼시다(모시다)’, ‘엳ᄌᆞᆸ다’ 등의 특수 어휘뿐만 아니라, 객체 높임의 선어말 어미 ‘-ᄉᆞᆸ-, -ᅀᆞᆸ-, -ᄌᆞᆸ-’ 등으로도 실현되었다.\n상대 높임은 화자가 대화의 상대인 청자를 높이거나 낮추는 것으로 현대 국어의 상대 높임은 주로 ‘-습니다’, ‘-아라/-어라’ 등의 종결 어미로 실현된다. 중세 국어의 상대 높임 또한 현대 국어와 마찬가지로 주로 종결 어미로 실현되었지만, 현대 국어와 달리 상대 높임의 선어말 어미 ‘-ᅌᅵ-’, ‘-ᅌᅵᆺ-’이 존재했다. 선어말 어미 ‘-ᅌᅵ-’는 평서형에서, ‘-ᅌᅵᆺ-’은 의문형에서 각각 나타나며 상대를 아주 높일 때 사용되었다.\n<보기>\nㄱ. (아버지께) 선생님께서는 책이 많으십니다.\nㄴ. (방송에서) 세종대왕이 한글을 창제했습니다.\nㄷ. (수업에서 선생님이) 발표할 어린이는 손 드시면 됩니다.\nㄹ. (어린 손자에게) 너희 엄마는 언제 출근하셨니?\nㅁ. (할아버지께) 아버지는 아직 병원에 가지 않았습니다.",
    "choices": [
      "O",
      "X"
    ],
    "answer": 0,
    "explanation": "이 선지는 맞는 설명입니다.\n\n원문 해설 — 아래 번호는 원래 문제의 선지 번호입니다. 다른 선지의 설명도 함께 제시합니다.\nㅁ의 주체인 ‘아버지’는 화자에게 높임의 대상이지만, 청자인 ‘할아버지’에게는 높임의 대상이 아니다. 따라서 화자는 주체인 ‘아버지’와 청자인 ‘할아버지’의 관계를 고려하여 ‘할아버지’ 앞에서 ‘아버지’를 높이지 않고 있다. 한편 청자인 ‘할아버지’는 화자에게 높임의 대상이다. 따라서 화자는 ‘-습니다’를 사용하여 상대 높임을 실현하고 있다.\n[오답풀이] ① ㄱ의 화자는 선생님의 소유물인 ‘책’에 대한 높임을 ‘-시-’로 실현함으로써 ‘선생님’을 간접적으로 높이고 있다. ② ㄴ은 방송이라는 공적 담화의 객관성을 고려해 ‘세종대왕’을 높이지 않고 있다. ③ ㄷ의 주체인 ‘어린이’는 화자에게 높임의 대상이 아니지만, 화자는 수업이라는 공적인 담화 상황을 고려하여 ‘어린이’에 대한 높임을 ‘-시-’로 실현하고 있다. ④ ㄹ의 주체인 ‘엄마’는 화자에게 높임의 대상이 아니지만, 청자인 ‘손자’에게는 높임의 대상이다. 따라서 화자는 주체인 ‘엄마’와 청자인 ‘손자’의 관계를 고려하여 ‘손자’ 앞에서 ‘엄마’에 대한 높임을 ‘-시-’로 실현하고 있다.",
