    "passage": "[자료]\n직접\n인용\n외국에 있는 형이 어제 전화로 “나는 내일 이곳에서 볼 시험 때문에 걱정이 많아.”라고 말했다.\n↓\n간접\n인용\n외국에 있는 형이 어제 전화로 자기는 오늘 그곳에서 볼 시험 때문에 걱정이 많다라고 말했다.\n판단 조건: 직접 인용을 간접 인용으로 바르게 바꿨는지 분석한다.",
