    "passage": "선생님: 피동은 주어가 다른 주체에 의해 어떤 동작을 당하거나 영향을 받는 것이고, 사동은 주어가 다른 대상에게 어떤 동작을 하게 하는 것을 의미합니다. 피동 표현과 사동 표현은 접미사에 의해 실현되기도 하는데, 피동 접미사와 사동 접미사가 같은 형태인 경우 문장에서의 쓰임을 바탕으로 그 접미사가 피동 접미사인지 사동 접미사인지를 파악해야 합니다.\n학생: 선생님, 그럼        ㉠       는 피동 접미사가 쓰인 경우이고,        ㉡       는 사동 접미사가 쓰인 경우이겠군요.\n선생님: 네, 맞습니다.",
