    "passage": "<보기>\n선생님:우리말에서 어근과 어근이 결합하여 합성 명사를 이룰 때, 뒤 어근의 예사소리가 된소리로 바뀌거나 두 어근 사이에 ‘ㄴ’이 첨가되기도 합니다. 다음은 이와 관련된 표준발음법의 규정을 정리한 것입니다.\n㉮‘ㄱ, ㄷ, ㅂ, ㅅ, ㅈ’으로 시작하는 단어 앞에 사이시옷이 올 때는 이들 자음만을 된소리로 발음하는 것을 원칙으로 하되, 사이시옷을 [ㄷ]으로 발음하는 것도 허용한다.\n㉯사이시옷 뒤에 ‘ㄴ, ㅁ’이 결합되는 경우에는 [ㄴ]으로, ‘이’ 음이 결합되는 경우에는 [ㄴㄴ]으로 발음한다.\n㉮는 앞 어근의 끝소리가 울림소리이고 뒤 어근의 첫소리가 안울림 예사소리이면 뒤의 예사소리가 된소리로 바뀌는 현상과 관련된 규정입니다. 그리고 ㉯는 앞 어근이 모음으로 끝나고 뒤 어근이 ‘ㄴ, ㅁ’으로 시작되면 앞 어근의 끝소리에 ‘ㄴ’ 소리가 첨가되는 현상, 혹은 앞 어근이 모음으로 끝나고 뒤 어근이 모음 ‘ㅣ’나 반모음 ‘ㅣ’로 시작되면 앞 어근의 끝소리와 뒤 어근의 첫소리에 각각 ‘ㄴ’이 첨가되는 현상과 관련된 규정입니다.\n그러면, 이를 바탕으로 다음 단어들에 대해 설명해 볼까요?\n빨랫돌[빨래똘/빨랟똘], 옷깃[옫낃],\n홑이불[혼니불], 뱃머리[밴머리], 깻잎[깬닙]",
    "choices": [
      "O",
      "X"
    ],
    "answer": 0,
    "explanation": "이 선지는 맞는 설명입니다.\n\n원문 해설 — 아래 번호는 원래 문제의 선지 번호입니다. 다른 선지의 설명도 함께 제시합니다.\n‘옷깃’은 명사 ‘옷’과 명사 ‘깃’이 결합하여 만들어진 합성 명사이다. 그리고 발음은 [옫낃]으로 둘째 어근의 첫소리 ‘ㄱ’이 된소리 ‘ㄲ’으로 바뀌는 현상이 나타난다. 하지만 이 때 나타나는 현상은 [ㄱ, ㄷ, ㅂ]으로 발음되는 받침 ‘ㄱ(ㄲ, ㅋ, ㄳ, ㄺ), ㄷ(ㅅ, ㅆ, ㅈ, ㅊ, ㅌ), ㅂ(ㅍ, ㄼ, ㄿ, ㅄ)’ 뒤에서 ‘ㄱ, ㄷ, ㅂ, ㅅ, ㅈ’은 된소리인 [ㄲ, ㄸ, ㅃ, ㅆ, ㅉ]으로 각각 발음되는 된소리되기에 해당하는 것으로, 사잇소리 현상의 앞 어근의 끝소리가 울림소리이고 뒤 어근의 첫소리가 안울림 예사소리이면 뒤의 예사소리가 된소리로 바뀌는 현상과는 다르다.\n[오답풀이] ① ‘빨랫돌’은 ‘빨래’와 ‘돌’이 결합하여 만들어진 합성 명사로, 앞 어근의 끝소리가 울림소리인데 뒤 어근의 첫소리인 안울림 예사소리가 된소리로 바뀐다는 점으로 볼 때, ㉮에 해당하는 예이다. ③ ‘홑이불’의 발음은 [혼니불]로, 발음할 때 ‘ㄴ’의 첨가가 나타난다. 하지만 ‘홑이불’은 접사 ‘홑-’과 명사 ‘이불’이 결합하여 만들어진 파생 명사이다. ④ ‘뱃머리’는 ‘배’와 ‘머리’가 결합하여 만들어진 합성 명사로, ‘ㅁ’으로 시작하는 뒤 어근의 앞에서 모음으로 끝난 앞 어근의 끝소리에 ‘ㄴ’이 첨가된다는 점으로 볼 때, ㉯에 해당하는 예이다. ⑤ ‘깻잎’은 ‘깨’와 ‘잎’이 결합하여 만들어진 합성 명사로, 앞 어근이 모음으로 끝나고 뒤 어근이 ‘ㅣ’로 시작되는데 앞 어근의 끝소리와 뒤 어근의 첫소리에 모두 ‘ㄴ’이 첨가된다는 점으로 볼 때, ㉯에 해당하는 예이다.",
