    "answer": 0,
    "explanation": "이 선지는 맞는 설명입니다.\n\n원문 해설 — 아래 번호는 원래 문제의 선지 번호입니다. 다른 선지의 설명도 함께 제시합니다.\n‘뜯어먹다’는 ‘뜯어’와 ‘먹다’ 사이에 ‘서’를 넣을 수 있으므로 ㉠에 해당하여 사전에 표제어로 실리지 않는다.\n① ‘헌가방’은 ‘헌 내 가방’과 같이 중간에 다른 말이 끼어들 수 있으므로 ㉠에 해당하며 사전에 표제어로 실리지 않는다.\n② ‘놓고가다’는 ‘놓고’와 ‘가다’ 사이에 ‘서’를 넣을 수 있으므로 ㉠에 해당하며 사전에 표제어로 실리지 않는다.\n④ ‘뜬소문’은 ‘근거 없이 떠도는 소문’이라는 의미로 중간에 다른 말이 끼어들면 의미가 변하므로 ㉡에 해당하여 사전에 표제어로 실린다.\n⑤ ‘알아듣다’는 ‘남의 말을 듣고 그 뜻을 알다’의 의미로 구성 요소의 배열이 순차적이지 않아 ㉢에 해당하는 합성어이며, 합성어는 사전에 표제어로 실리므로 적절하다.",
