    "answer": 1,
    "explanation": "이 선지는 틀린 설명입니다.\n\n원문 해설 — 아래 번호는 원래 문제의 선지 번호입니다. 다른 선지의 설명도 함께 제시합니다.\n‘만큼’은 관형어 ‘노력한’의 수식을 받는 의존 명사이므로, 앞말과 띄어 써야 한다.\n[오답풀이] ② ‘만큼’은 체언 ‘형’ 뒤에 붙는 조사이므로 앞말과 붙여 써야 한다. ③ ‘만큼’은 관형어 ‘몰랐던’의 수식을 받는 의존 명사이므로, 앞말과 띄어 써야 한다. ④ ‘만큼’은 관형어 ‘바랄’의 수식을 받는 의존 명사이므로 앞말과 띄어 써야 한다. ⑤ ‘만큼’은 체언 ‘고향’ 뒤에 붙는 조사이므로 앞말과 붙여 써야 한다.",
