    "explanation": "이 선지는 맞는 설명입니다.\n\n원문 해설 — 아래 번호는 원래 문제의 선지 번호입니다. 다른 선지의 설명도 함께 제시합니다.\n현대 국어의 ‘살코기’는 중세 국어의 ‘ᄉᆞᆯㅎ’과 ‘고기’가 결합하여 ‘ㅎ 종성 체언’의 흔적이 남은 단어이다. 제시된 중세 국어 자료에 의하면, ‘ㅎ 종성 체언’은 단독형으로 쓰일 때에는 ‘ㅎ’이 나타나지 않았으므로, ‘살코기’의 ‘살’은 중세 국어에서 단독으로 쓰일 경우 ‘ᄉᆞᆯ’의 형태로 사용되었을 것이다.\n[오답풀이] ① ‘안팎’은 ‘안’과 ‘밖’이 어울려 쓰인 것으로 ‘안ㅎ’의 흔적이 남은 경우에 해당한다. ② ‘수캐’는 중세 국어에서 ‘수ㅎ’와 ‘개’가 어울려 쓰인 것으로 ‘수’의 ‘ㅎ’ 종성이 ‘ㄱ’과 어울려 ‘ㅋ’이 되는 거센소리되기가 이루어진 것이다. ④ 중세 국어에서 ‘나라’는 ‘ㅎ 종성 체언’으로, 모음으로 시작하는 조사 ‘이’와 결합할 경우 ‘ㅎ’을 이어 적어 ‘나라히’와 같은 형태로 나타난다. ⑤ ‘암평아리’는 중세 국어에서 ‘ㅎ 종성 체언’인 ‘암ㅎ’과 ‘병아리’가 결합하여 ‘암평아리’가 된 단어로, ‘ㅎ 종성 체언’의 흔적이 남은 단어이다.",
