    "passage": "한글\n맞춤법\n【제31항】두 말이 어울릴 적에 ‘ㅎ’ 소리가 덧나는 것은 소리대로 적는다.\n∘수캐(○) / 수개(×)\n∘살코기(○) / 살고기(×)\n관련자료\n중세 국어에서는 ‘ᄉᆞᆯㅎ’, ‘암ㅎ[雌]’, ‘수ㅎ[雄]’, ‘안ㅎ[內]’, ‘나라ㅎ’ 등의 ‘ㅎ 종성 체언’이 있었다. ‘ㅎ 종성 체언’은 단독형으로 쓰일 때에는 ‘ㅎ’이 나타나지 않지만, 아래와 같은 경우 ‘ㅎ’이 나타나기도 하였다.\n‘ㅎ’이 나타나는 경우\n예\n모음으로 시작하는 말과 결합하는 경우 ‘ㅎ’을 이어 적음.\n하ᄂᆞᆯㅎ+이\n→하ᄂᆞᆯ히(하늘이)\n자음 ‘ㄱ, ㄷ, ㅂ’으로 시작하는 말과 결합하는 경우 ‘ㅋ, ㅌ, ㅍ’이 됨.\n고ㅎ+기리\n→고키리(코끼리)\n현대 국어에서는 몇 개의 복합어에서만 ‘ㅎ’ 종성 체언의 흔적이 남아 있는데, ‘수캐’, ‘살코기’, ‘암평아리’ 등이 그에 해당한다.",
