    "passage": "<보기1>\n[중세 국어] 보살(菩薩)이 ㉠어느 나라해 ᄂᆞ리시게 ᄒᆞ려뇨\n[현대 국어] 보살이 어느 나라에 내리시도록 하려는가?\n[중세 국어] ㉡어늬 구더 병불쇄(兵不碎)ᄒᆞ리ᅌᅵᆺ고\n[현대 국어] 어느 것이 굳어 군대가 부수어지지 않겠습니까?\n[중세 국어] 져믄 아ᄒᆡ ㉢어느 듣ᄌᆞᄫᅩ리ᅌᅵᆺ고\n[현대 국어] 어린 아이가 어찌 듣겠습니까?\n[중세 국어] 미혹(迷惑) ㉣어느 플리\n[현대 국어] 미혹한 마음을 어찌 풀겠는가?\n[중세 국어] 이 두 말ᄋᆞᆯ ㉤어늘 종(從)ᄒᆞ시려뇨\n[현대 국어] 이 두 말을 어느 것을 따르시겠습니까?\n<보기2>\n어느 01「관형사」\n둘 이상의 것 가운데 대상이 되는 것이 무엇인지 물을 때 쓰는 말.\n어느 02「대명사」『옛말』\n어느 것.\n어느 03「부사」『옛말』\n‘어찌’의 옛말.",
