    "passage": "<보기1>\n[중세 국어] 보살(菩薩)이 ㉠어느 나라해 ᄂᆞ리시게 ᄒᆞ려뇨\n[현대 국어] 보살이 어느 나라에 내리시도록 하려는가?\n[중세 국어] ㉡어늬 구더 병불쇄(兵不碎)ᄒᆞ리ᅌᅵᆺ고\n[현대 국어] 어느 것이 굳어 군대가 부수어지지 않겠습니까?\n[중세 국어] 져믄 아ᄒᆡ ㉢어느 듣ᄌᆞᄫᅩ리ᅌᅵᆺ고\n[현대 국어] 어린 아이가 어찌 듣겠습니까?\n[중세 국어] 미혹(迷惑) ㉣어느 플리\n[현대 국어] 미혹한 마음을 어찌 풀겠는가?\n[중세 국어] 이 두 말ᄋᆞᆯ ㉤어늘 종(從)ᄒᆞ시려뇨\n[현대 국어] 이 두 말을 어느 것을 따르시겠습니까?\n<보기2>\n어느 01「관형사」\n둘 이상의 것 가운데 대상이 되는 것이 무엇인지 물을 때 쓰는 말.\n어느 02「대명사」『옛말』\n어느 것.\n어느 03「부사」『옛말』\n‘어찌’의 옛말.",
    "choices": [
      "O",
      "X"
    ],
    "answer": 0,
    "explanation": "이 선지는 맞는 설명입니다.\n\n원문 해설 — 아래 번호는 원래 문제의 선지 번호입니다. 다른 선지의 설명도 함께 제시합니다.\n㉤은 ‘어느’에 목적격 조사가 결합한 형태로, ㉤에 사용된 ‘어느’는 현대 국어의 ‘어느 것’이라는 의미를 가진 옛말이므로 대명사이다. 이는 <보기 2>의 ‘어느 02’에 해당하므로 적절하지 않다.\n① ㉠은 체언 ‘나라’를 수식하고 있으므로 관형사이다. 따라서 <보기 2>의 ‘어느 01’과 품사가 동일하다는 진술은 적절하다. ② ㉡은 ‘어느’에 주격 조사 ‘ㅣ’가 붙은 형태이다. ㉡에 사용된 ‘어느’는 현대 국어의 ‘어느 것’이라는 의미를 가진 옛말이므로 대명사이다. 따라서 <보기 2>의 ‘어느 02’에 해당하므로 적절하다. ③ ㉢은 용언인 ‘듣ᄌᆞᄫᅩ리ᅌᅵᆺ고’를 수식하고 있으므로 부사이다. 따라서 <보기 2>의 ‘어느 03’으로 쓰였다는 진술은 적절하다. ④ ㉣은 용언인 ‘플리’를 수식하는 부사이고, <보기 2>의 ‘어느 01’은 관형사이므로 적절하다.",
