    "answer": 1,
    "explanation": "이 선지는 틀린 설명입니다.\n\n원문 해설 — 아래 번호는 원래 문제의 선지 번호입니다. 다른 선지의 설명도 함께 제시합니다.\n<보기>의 [탐구 결과]에 따르면, ㄱ과 ㄴ은 판정 의문문, ㄷ과 ㄹ은 설명 의문문이다. 그리고 4문단에 의하면, ㄱ의 ‘가’와 ㄷ의 ‘고’는 의문문을 만드는 보조사이고, ㄴ의 ‘-녀’와 ㄹ의 ‘-뇨’는 의문문을 만드는 종결 어미이다. 중세 국어에서는 판정 의문문에는 ‘아/어’ 계통의 보조사나 종결 어미가 사용되었고, 설명 의문문에는 ‘오’ 계통의 보조사나 종결 어미가 사용되었다. 따라서 <보기>의 사례들을 통해 중세 국어에서는 판정 의문문에 사용되는 보조사나 종결 어미의 형태가 설명 의문문과 달랐다고 판단할 수 있다.",
