    "explanation": "이 선지는 맞는 설명입니다.\n\n원문 해설 — 아래 번호는 원래 문제의 선지 번호입니다. 다른 선지의 설명도 함께 제시합니다.\n㉢에서는 ‘선혜’를 높이는 주체 높임 선어말 어미인 ‘-샤-’가 사용되었음을 확인할 수 있다.\n[오답풀이] ① ㉠은 현대 국어에서 ‘이르되’로 쓰는 것으로 보아, 중세 국어에는 두음 법칙이 적용되지 않았음을 확인할 수 있다.\n② ㉡은 현대 국어에서 ‘좇음이’로 쓰는 것으로 보아, 중세 국어에는 이어 적기가 사용되었음을 확인할 수 있다.\n④ ㉣은 현대 국어에서 ‘석 달을’로 쓰는 것으로 보아, 중세 국어에는 체언에 조사가 결합할 때 모음조화를 지켰음을 확인할 수 있다.\n⑤ ㉤에서 ‘ㅿ’은 현대 국어에서 쓰이지 않는 자음임을 확인할 수 있다.",
